export function Affordance({
  cues = {{cues}},
  elementType = "{{elementType}}",
  label = "{{label}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 22, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa", textAlign: "center" }}>
      {elementType === "button" && (
        <button type="button" style={{ font: "600 14px system-ui, sans-serif", padding: "10px 18px", borderRadius: 8, cursor: "pointer", color: "#241430", background: cues ? accent : "transparent", border: "none", boxShadow: cues ? "0 3px 0 rgba(36,20,48,.25)" : "none" }}>{label}</button>
      )}
      {elementType === "toggle-switch" && (
        <span style={{ display: "inline-block", width: 44, height: 24, borderRadius: 999, background: cues ? accent : "#24143022", position: "relative", boxShadow: cues ? "inset 0 1px 3px rgba(36,20,48,.3)" : "none" }}>
          <i style={{ position: "absolute", top: 2, left: cues ? 22 : 2, width: 20, height: 20, borderRadius: 999, background: "#fff", display: "block", boxShadow: cues ? "0 1px 2px rgba(36,20,48,.4)" : "none" }} />
        </span>
      )}
      {elementType === "link" && (
        <a href="#" style={{ color: cues ? accent : "#241430", textDecoration: cues ? "underline" : "none", fontWeight: 600 }}>{label}</a>
      )}
      <p style={{ margin: "16px 0 0" }}>{cues ? "With" : "Without"} affordance cues &mdash; same element, same behaviour, different visual hinting</p>
    </div>
  );
}
